public static class StackCheck
{
    public static List<object> Check(string[] commands)
    {
        var stack = new TypedStack<int>();
        var words = new TypedStack<string>();
        var results = new List<object>();
        foreach (var command in commands)
        {
            var p = command.Split(' ');
            try
            {
                switch (p[0])
                {
                    case "push": stack.Push(int.Parse(p[1])); break;
                    case "pop": results.Add(stack.Pop()); break;
                    case "peek": results.Add(stack.Peek()); break;
                    case "count": results.Add(stack.Count); break;
                    case "empty": results.Add(stack.IsEmpty); break;
                }
            }
            catch (InvalidOperationException)
            {
                results.Add("error");
            }
        }
        words.Push("ok");
        results.Add(words.Pop());
        return results;
    }
}

